(()=>{const root=document.documentElement, zh=root.lang.startsWith('zh'), system=matchMedia('(prefers-color-scheme: dark)');let mode='system';try{let v=localStorage.getItem('lgt-appearance');if(['system','light','dark'].includes(v))mode=v}catch{}const details=[...document.querySelectorAll('.nav-control')], lang=document.querySelector('#language-control'), theme=document.querySelector('#appearance-control'), trigger=theme.querySelector('summary'), options=[...theme.querySelectorAll('button[data-mode]')];
if(!theme||!lang)return;const labels=zh?{system:'跟随系统',light:'浅色',dark:'深色'}:{system:'System',light:'Light',dark:'Dark'};function render(){let effective=mode==='system'?(system.matches?'dark':'light'):mode;root.dataset.theme=effective;root.style.colorScheme=effective;document.querySelectorAll('.hero-icon,.brand-icon').forEach(i=>i.src=i.src.replace(/app-icon-(?:light|dark)\.png$/,`app-icon-${effective}.png`));let favicon=document.getElementById('dynamic-favicon');if(favicon)favicon.href=favicon.href.replace(/favicon-(?:light|dark)-32\.png$/,`favicon-${effective}-32.png`);trigger.querySelector('span').textContent={system:'▣',light:'☀',dark:'☾'}[mode];trigger.setAttribute('aria-label',(zh?'外观：':'Appearance: ')+labels[mode]);trigger.title=trigger.getAttribute('aria-label');for(let b of options){let selected=b.dataset.mode===mode;b.setAttribute('aria-pressed',String(selected));b.querySelector('.check').textContent=selected?'✓':''}}for(let b of options)b.addEventListener('click',()=>{mode=b.dataset.mode;try{localStorage.setItem('lgt-appearance',mode)}catch{}render();theme.open=false;trigger.focus()});system.addEventListener?.('change',()=>{if(mode==='system')render()});for(let d of details)d.addEventListener('toggle',()=>{if(d.open)for(let other of details)if(other!==d)other.open=false});document.addEventListener('click',e=>{for(let d of details)if(!d.contains(e.target))d.open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape')for(let d of details)if(d.open){d.open=false;d.querySelector('summary').focus()}});for(let a of lang.querySelectorAll('a'))a.addEventListener('click',()=>{if(['#downloads','#history'].includes(location.hash)&&!location.pathname.includes('/changelog/'))a.hash=location.hash});render()})();
